mkdir -p exercice_020 && { echo "Date: $(date)"; echo "Hostname: $(hostname)"; echo "Top 5 paquets les plus lourds :"; dpkg-query -W -f='${Installed-Size}\t${Package}\n' 2>/dev/null | sort -nr | head -5 | awk '{printf "%d. %s - %s\n", NR, $2, $1}'; } > exercice_020/rapport.txt && sed 's/^/>> /' exercice_020/rapport.txt > exercice_020/rapport_formatted.txt && wc -l < exercice_020/rapport_formatted.txt > exercice_020/line_count.txt
